import { NextResponse } from 'next/server'; import {connectDB} from '../../../lib/db'; import {getUserFromRequest} from '../../../lib/auth'; import {InterviewReport} from '../../../lib/models'; import {generateInterviewReport} from '../../../lib/ai'; import {PDFParse} from 'pdf-parse';
export async function GET(){await connectDB();const user=await getUserFromRequest();if(!user)return NextResponse.json({message:'Token not provided.'},{status:401});const reports=await InterviewReport.find({user:user.id}).sort({createdAt:-1}).select('-resume -selfDescription -jobDescription -__v -technicalQuestions -behavioralQuestions -skillGaps -preparationPlan');return NextResponse.json({interviewReports:reports});}
export async function POST(request){await connectDB();const user=await getUserFromRequest();if(!user)return NextResponse.json({message:'Token not provided.'},{status:401});try{const form=await request.formData();const selfDescription=String(form.get('selfDescription')||'').trim().slice(0,10000);const jobDescription=String(form.get('jobDescription')||'').trim().slice(0,20000);if(!jobDescription)return NextResponse.json({message:'Please enter a job description'},{status:400});if(!selfDescription)return NextResponse.json({message:'Please enter a self description'},{status:400});const file=form.get('resume');let resume='';if(file&&typeof file!=='string'){if(file.type!=='application/pdf')return NextResponse.json({message:'Resume must be a PDF file'},{status:400});const bytes=Buffer.from(await file.arrayBuffer());if(bytes.length>5*1024*1024)return NextResponse.json({message:'Resume exceeds the 5 MB limit'},{status:413});const parser=new PDFParse({data:bytes});try{const parsed=await parser.getText();resume=(parsed.text||'').slice(0,50000);}finally{await parser.destroy();}}const aiReport=await generateInterviewReport({resume:resume||'Not provided',selfDescription: selfDescription||'Not provided',jobDescription:jobDescription||'Not provided'});const normalizedReport={...aiReport,title:String(aiReport.title||'Personalized Interview Report').trim(),matchScore:Math.max(0,Math.min(100,Number(aiReport.matchScore)||0)),skillGaps:Array.isArray(aiReport.skillGaps)?aiReport.skillGaps.map(g=>{const severity=String(g.severity||'medium').toLowerCase();return {...g,severity:['low','medium','high'].includes(severity)?severity:'medium'}}):[],preparationPlan:Array.isArray(aiReport.preparationPlan)?aiReport.preparationPlan.map((p,i)=>{const parsed=Number(String(p.day||'').match(/\d+/)?.[0]);return {...p,day:parsed>0?parsed:i+1,tasks:Array.isArray(p.tasks)?p.tasks:[]}}):[]};const report=await InterviewReport.create({user:user.id,resume, selfDescription,jobDescription,...normalizedReport});return NextResponse.json({interviewReport:report},{status:201});}catch(error){console.error('Failed to generate interview report',error);const message=String(error?.message||'');const aiError=message.includes('API key')||message.includes('UNAUTHENTICATED')||message.includes('GOOGLE_GENAI_API_KEY');const aiUnavailable=message.includes('404')||message.includes('NOT_FOUND')||message.includes('429')||message.includes('RESOURCE_EXHAUSTED')||message.includes('Unavailable')||message.includes('quota');const invalidJson=error instanceof SyntaxError;if(aiError)return NextResponse.json({message:'AI authentication failed. Check GOOGLE_GENAI_API_KEY.'},{status:503});if(aiUnavailable)return NextResponse.json({message:'The AI service is temporarily unavailable or its model quota changed. Please try again.'},{status:503});if(invalidJson)return NextResponse.json({message:'The AI returned an unreadable report. Please try again.'},{status:502});return NextResponse.json({message:'Failed to generate interview report'},{status:500});}}
